'use strict';

// Fixture stand-in for an INSTALLED dependency (dependency-upgrade-contract eval).
//
// There is no registry in an eval run, so this module resolves its own API
// surface from the version pinned in the project's package.json instead of
// from its own on-disk copy. Bumping `devDependencies.slugmaker` therefore
// behaves exactly as `npm install` would - the 1.x surface disappears and the
// 2.x surface appears - with no network and no install step.
//
//   1.x  ->  exports { makeSlug, version }
//   2.x  ->  exports { toSlug,   version }        (makeSlug REMOVED in 2.0.0)
//
// The slugging behaviour is identical across both; only the exported name
// changes. That is deliberate: this case measures whether the contract was
// followed, not whether a behaviour difference was noticed.
//
// See CHANGELOG.md beside this file - it is the changelog the Upgrade brief
// is supposed to be read from.

const fs = require('node:fs');
const path = require('node:path');

function pinnedVersion() {
  const manifestPath = path.join(__dirname, '..', '..', 'package.json');
  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  const dev = manifest.devDependencies || {};
  const deps = manifest.dependencies || {};
  const raw = String(dev.slugmaker || deps.slugmaker || '');
  return raw.replace(/^[\^~=v]+/, '').trim();
}

function majorOf(version) {
  const first = version.split('.')[0];
  const parsed = parseInt(first, 10);
  if (Number.isNaN(parsed)) {
    throw new Error(
      'slugmaker: cannot read a version for this package from package.json ' +
      '(got "' + version + '"). The fixture resolves its API surface from the pin.'
    );
  }
  return parsed;
}

function slugify(text, options) {
  const opts = options || {};
  const separator = typeof opts.separator === 'string' ? opts.separator : '-';
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, separator);
}

const version = pinnedVersion();
const major = majorOf(version);

const api = { version: version };
if (major >= 2) {
  api.toSlug = slugify;
} else {
  api.makeSlug = slugify;
}

module.exports = api;
